#!/usr/bin/env bash
# Wrapper for `cargo check` / `cargo build` that continuously cleans macOS
# resource-fork pollution during the entire build.
#
# Why: tauri 2.x build.rs reads `target/**/autogenerated/*.toml` after writing
# it. On macOS, every write produces a sibling `._<filename>` resource-fork
# file via the kernel's copyfile machinery, which `COPYFILE_DISABLE=1` does
# NOT suppress for `std::fs::write` (Rust bypasses the system copyfile call).
# The build.rs then panics on `._default.toml: stream did not contain valid
# UTF-8`. This script runs a background watcher that sweeps those `._*.toml`
# files every 100ms throughout the entire cargo invocation.
#
# Usage: scripts/cargo-check-clean.sh check
#        scripts/cargo-check-clean.sh build
#        scripts/cargo-check-clean.sh tauri dev
#
# Notes:
# - Finder / Spotlight / Time Machine can re-create the resource forks faster
#   than the watcher can delete them, but 100ms is fast enough for the tauri
#   build.rs read step (which happens seconds after the write).
# - For best results, also disable Spotlight indexing on /Volumes/CC/ via
#   `sudo mdutil -i off /Volumes/CC` (optional).

set -euo pipefail

# Locate repo root (works whether invoked from anywhere)
ROOT="$(git rev-parse --show-toplevel 2>/dev/null || pwd)"

# Initial sweep
find "$ROOT/src-tauri/target" -name "._*.toml" -type f -delete 2>/dev/null || true

# Also set COPYFILE_DISABLE for any subprocess that respects it
export COPYFILE_DISABLE=1

# Start a background watcher that keeps sweeping ._*.toml files during cargo
WATCHER_OUT="$(mktemp -t cargo-check-clean.XXXXXX)"
(
  while true; do
    find "$ROOT/src-tauri/target" -name "._*.toml" -type f -delete 2>/dev/null || true
    sleep 0.1
  done
) > "$WATCHER_OUT" 2>&1 &
WATCHER_PID=$!

# Always kill the watcher, even on failure
cleanup() {
  kill "$WATCHER_PID" 2>/dev/null || true
  wait "$WATCHER_PID" 2>/dev/null || true
  rm -f "$WATCHER_OUT"
}
trap cleanup EXIT INT TERM

# Final sweep right before cargo starts (in case the watcher missed anything)
find "$ROOT/src-tauri/target" -name "._*.toml" -type f -delete 2>/dev/null || true

echo "[cargo-check-clean] watching for ._*.toml; running: cargo $*"

# Delegate to the real cargo
exec cargo "$@"
